import { useMemo } from 'react';

import { useCommercialSelectOptions } from 'components/Filter/hooks/useCommercialSelectOptions';
import { FieldProps } from 'components/Filter/types';
import {
  findFilterClearSentinelOption,
  shouldShowFilterSelectClearIndicator,
} from 'components/Filter/utils/filterClearableSelectPolicy';
import { Select } from 'components/Form';
import { FilterDataAccessor } from 'domain/Filter/FilterDataAccessor';
import { useGoogleAnalytics, usePageFilterData } from 'hooks';
import { useFilterRules } from 'hooks/useFilters/core/useFilterRules';
import { Option } from 'models/Filters';
import { COMMERCIAL_RESULTS_PAGE_NAME } from 'pages/pillars/ValueCreation/CommercialResults/constants';

type FilterDimensionWithEnabled = {
  enabled?: boolean;
};

export const BrandsField = ({
  dataTestId,
  fieldKey,
  pageName,
  onValueChange,
  getCurrentValue,
}: FieldProps) => {
  const trackGA = useGoogleAnalytics();
  const { dataFilters, formDataFilters, defaults } =
    usePageFilterData(pageName);
  const { getFieldConfig } = useFilterRules();

  const kpiValue = getCurrentValue('kpis');
  const countryValue = getCurrentValue('country');
  const zoneValue = getCurrentValue('zone');
  const growthLeverValue = getCurrentValue('growth_levers');
  const brandClassValue = String(
    getCurrentValue('brand_filter_groupings') ??
      defaults['brand_filter_groupings'] ??
      '',
  );
  const formValue = getCurrentValue(fieldKey);
  const portfolioValue = getCurrentValue('portfolios');
  const beerPriceSegmentValue = getCurrentValue('beer_price_segment');
  const brandValue = getCurrentValue('brands');

  const fieldConfig = useMemo(
    () =>
      getFieldConfig('brands', {
        kpi: kpiValue,
        growthLever: growthLeverValue,
        country: countryValue,
        brand: brandValue,
        zone: zoneValue,
        brandClass: brandClassValue,
        portfolio: portfolioValue,
        beerPriceSegment: beerPriceSegmentValue,
      }),
    [
      getFieldConfig,
      kpiValue,
      growthLeverValue,
      countryValue,
      zoneValue,
      brandClassValue,
      portfolioValue,
      beerPriceSegmentValue,
      brandValue,
    ],
  );

  const optionsFromAccessor: Option[] = useMemo(() => {
    const accessor = FilterDataAccessor.getInstance();
    const sourceDataFilters =
      pageName === COMMERCIAL_RESULTS_PAGE_NAME ? formDataFilters : dataFilters;
    const fallbackDataFilters =
      pageName === COMMERCIAL_RESULTS_PAGE_NAME ? undefined : formDataFilters;
    const options = accessor.getOptions(fieldKey, sourceDataFilters, {
      country: countryValue,
    }) as Option[];
    if (options.length > 0) return options;
    return accessor.getOptions(fieldKey, fallbackDataFilters, {
      country: countryValue,
    }) as Option[];
  }, [fieldKey, pageName, dataFilters, formDataFilters, countryValue]);

  const {
    isCommercialPage,
    commercialDisplayValue,
    selectableOptions: commercialSelectableOptions,
  } = useCommercialSelectOptions({
    pageName,
    rawOptions: optionsFromAccessor,
    formValue,
    defaultValue: fieldConfig.defaultValue,
  });

  const rawOptions = useMemo(() => {
    if (isCommercialPage) {
      return optionsFromAccessor;
    }

    const hasAll = optionsFromAccessor.some((opt) => opt.value === 'All');
    if (!hasAll && optionsFromAccessor.length > 0) {
      return [{ value: 'All', label: 'All' }, ...optionsFromAccessor];
    }
    return optionsFromAccessor;
  }, [optionsFromAccessor, isCommercialPage]);

  const selectableOptions = isCommercialPage
    ? commercialSelectableOptions
    : rawOptions;

  const displayValue = useMemo(() => {
    if (isCommercialPage) {
      return commercialDisplayValue;
    }
    if (fieldConfig.disabled && fieldConfig.placeholder) return null;
    if (formValue != null && formValue !== '') {
      return formValue;
    }
    if (formValue === '' || formValue === null) {
      return null;
    }
    if (fieldConfig.defaultValue) return fieldConfig.defaultValue;
    return null;
  }, [
    isCommercialPage,
    commercialDisplayValue,
    formValue,
    fieldConfig.defaultValue,
    fieldConfig.disabled,
    fieldConfig.placeholder,
  ]);

  const handleValueChange = (option: Option) => {
    if (!option?.value) return;

    trackGA({
      event_category: 'Brand Select',
      event_action: 'Select',
      event_label: option?.value as string,
    });
    onValueChange(fieldKey, option);
    onValueChange('sub_brands', { value: null, label: '' });
  };

  if (fieldConfig.hidden) {
    return null;
  }

  const clearable = shouldShowFilterSelectClearIndicator(
    pageName,
    fieldKey,
    String(formValue ?? ''),
    rawOptions,
    defaults,
  );

  const commercialBrandDimension = formDataFilters?.[
    fieldKey
  ] as FilterDimensionWithEnabled;
  const commercialBrandDisabled =
    isCommercialPage && commercialBrandDimension?.enabled === false;

  return (
    <Select
      dataTestId={dataTestId ? `${dataTestId}-${fieldKey}` : undefined}
      id={`${fieldKey}-select`}
      label={fieldConfig.label}
      value={displayValue}
      options={selectableOptions}
      clearable={clearable}
      onValueChange={(option) => {
        const opt = Array.isArray(option) ? option[0] : option;
        if (opt === '') {
          const target = findFilterClearSentinelOption(
            fieldKey,
            rawOptions,
            defaults,
          );
          if (target?.value) {
            onValueChange(fieldKey, target);
            onValueChange('sub_brands', { value: null, label: '' });
          }
          return;
        }
        handleValueChange(opt as Option);
      }}
      placeholder={fieldConfig.placeholder || 'Select a brand'}
      disabled={fieldConfig.disabled || commercialBrandDisabled}
      searchable
    />
  );
};

export default BrandsField;
